CREATE VIEW view_coupon_history AS select `h`.`id` AS `id`,`h`.`coupon_id` AS `coupon_id`,`h`.`member_id` AS `member_id`,`h`.`coupon_code` AS `coupon_code`,`h`.`qrcode_url` AS `qrcode_url`,`h`.`get_type` AS `get_type`,`h`.`get_time` AS `get_time`,`h`.`use_status` AS `use_status`,`h`.`use_time` AS `use_time`,`h`.`order_id` AS `order_id`,`h`.`order_sn` AS `order_sn`,`h`.`start_time` AS `start_time`,`h`.`end_time` AS `end_time`,`h`.`note` AS `note`,`h`.`del_flag` AS `del_flag`,`c`.`name` AS `coupon_name`,`c`.`coupon_type` AS `coupon_type`,`c`.`description` AS `coupon_description`,`c`.`del_flag` AS `coupon_del_flag` from (`sms_coupon_history` `h` left join `sms_coupon` `c` on((`h`.`coupon_id` = `c`.`id`))) where ((`h`.`del_flag` = 0) and (`c`.`del_flag` = 0));
